let toast_timer=0,Utils={app:null,cache_data:{},has_key(){return wp.hooks.applyFilters("shipflex.has_key",!1)},generate_uuid(){return Math.random().toString(36).slice(2,9)},async generate_key(t){var e=new TextEncoder,e=await crypto.subtle.digest("SHA-256",e.encode(JSON.stringify(t)));return Array.from(new Uint8Array(e)).map(t=>t.toString(16).padStart(2,"0")).join("")},set_cache_data(t,e){this.cache_data[t]=e},get_cache_data(t){return this.cache_data?.[t]},set_toast_message(t,e="error"){t&&(this.app.toast_message=t,this.app.show_toast_message=!0,this.app.toast_message_type=e,clearTimeout(toast_timer),toast_timer=setTimeout(()=>this.app.show_toast_message=!1,3500))}},Feature_Base_Component={props:{featureData:{default:null},tierNo:{default:1,type:Number},additionalTier:{type:Boolean,default:!1}},emits:["update"],data(){return{collapse:!1,condition_groups:[]}},updated(){this.$emit("update",this.$data),console.log(this.$data)},methods:{add_condition_group(){Array.isArray(this.condition_groups)||(this.condition_groups=[]),this.condition_groups.push({id:Utils.generate_uuid()})},delete_condition(t){this.condition_groups.splice(t,1)}}};export{Utils,Feature_Base_Component};